        ["process.waitExit.return.exitCode.label"] = "Exit code",
        ["process.waitExit.return.exitCode.hint"] = "The code the script ended with; 0 usually means it went well. Kept apart from the message because a script often means something by the code it chose: a 3 can say \"nothing to do today\" without being a failure, and a macro can branch on it once the failure rule has let it carry on.",
        ["process.exists.name"] = "Program Running",
