        ["process.info.return.program.label"] = "Program",
        ["process.info.return.program.hint"] = "The program as one record: info is its file, empty when Windows will not say it; then id, name, memoryMb (the memory it holds, in megabytes) and cpuSeconds, the processor time it has used. Read one part of it with field($name, \"id\").",
        ["process.kill.name"] = "Stop Program",
        ["process.kill.desc"] = "Close a program, asking it to exit first unless told to be firm.",
        ["process.kill.window.label"] = "Program",
        ["process.kill.window.hint"] = "The program to close. A window or a handle closes that one program; a process name closes every program of that name.",
        ["process.kill.force.label"] = "Force close",
        ["process.kill.force.hint"] = "Close it at once instead of asking it to exit. Off by default.",
