        ["command.run.name"] = "Run Command",
        ["command.run.desc"] = "Run a command line and collect what it printed.",
        ["command.run.commandFile.label"] = "Command",
        ["command.run.commandFile.hint"] = "The program to run, such as cmd.exe or a full path to it.",
        ["command.run.commandArguments.label"] = "Arguments",
        ["command.run.commandArguments.hint"] = "What to pass to the command, read as one value. Empty, which is the default, passes nothing.",
        ["command.run.workingDirectory.label"] = "Working folder",
        ["command.run.workingDirectory.hint"] = "Folder to run the command in. Empty, which is the default, leaves it in the folder WhaleGenie itself was started in.",
        ["command.run.environment.label"] = "Environment variables",
        ["command.run.environment.hint"] = "One NAME=value per line for the command to run with. Empty, which is the default, runs it with WhaleGenie's own environment. Lines starting with # are skipped.",
        ["command.run.standardInput.label"] = "Standard input",
        ["command.run.standardInput.hint"] = "What the command reads on its standard input. Empty, which is the default, gives it nothing to read. Sent as UTF-8, and $name is replaced by what that variable holds.",
        ["command.run.streamOutput.label"] = "Write output to the log as it arrives",
        ["command.run.streamOutput.hint"] = "Put every line the command prints into the run log while it is still running, which is how a long build or script can be watched. The output result still holds everything the command printed. Off by default.",
        ["command.run.outputEncoding.label"] = "Output encoding",
        ["command.run.outputEncoding.hint"] = "The code page the command prints in; this machine's own by default. That is what the programs Windows ships with, cmd.exe, Windows PowerShell and Python, write in when they are not talking to a screen. A program that prints UTF-8 whichever machine it is on, Node.js for one, has to be read that way instead.",
        ["command.run.returns.label"] = "Returns",
        ["command.run.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["command.run.return.output.label"] = "Output",
