        ["screen.list.name"] = "List Displays",
        ["screen.list.desc"] = "Read how the desk is laid out: every display and the rectangle it holds.",
        ["screen.list.returns.label"] = "Returns",
        ["screen.list.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["screen.list.return.displays.label"] = "Displays",
        ["screen.list.return.displays.hint"] = "One record to a display, in the order Windows lists them: x and y, the middle of the display, then left, top, width, height, right, bottom, primary, and box, the rectangle written as left,top,width,height, which a region field takes as it stands. A display to the left of the primary one starts at a negative left, which is what a step aiming at it needs. Read one part of one of them with field(get($name, 0), \"left\"), and walk them all with forEach.",
        ["system.environment.name"] = "Environment Variable",
        ["system.environment.desc"] = "Read an environment variable.",
