        ["system.setEnvironment.return.value.label"] = "Value",
        ["system.setEnvironment.return.value.hint"] = "What the variable holds after the write, read back from the machine.",
        ["system.readRegistry.name"] = "Read Registry Value",
        ["system.readRegistry.desc"] = "Read one value out of the registry.",
        ["system.readRegistry.hive.label"] = "Where it is",
        ["system.readRegistry.hive.hint"] = "Which set of settings: this user's own, or the ones that hold for the whole machine. This user is the default and needs no administrator rights.",
        ["system.readRegistry.registryPath.label"] = "Key",
        ["system.readRegistry.registryPath.hint"] = "The key under that root, written as folders separated by backslashes, for example Software\\Vendor\\App. The root is the word above, so a path that starts with HKEY_ or with a backslash is refused.",
        ["system.readRegistry.valueName.label"] = "Value name",
