        ["system.writeRegistry.hive.label"] = "Where it is",
        ["system.writeRegistry.hive.hint"] = "Which set of settings: this user's own, or the ones that hold for the whole machine. This user is the default and needs no administrator rights.",
        ["system.writeRegistry.registryPath.label"] = "Key",
        ["system.writeRegistry.registryPath.hint"] = "The key under that root, written as folders separated by backslashes, for example Software\\Vendor\\App. The root is the word above, so a path that starts with HKEY_ or with a backslash is refused.",
        ["system.writeRegistry.valueName.label"] = "Value name",
        ["system.writeRegistry.valueName.hint"] = "Which value inside that key. Empty means the key's own default value, the one the registry editor shows as (Default).",
        ["system.writeRegistry.registryType.label"] = "Kind of value",
        ["system.writeRegistry.registryType.hint"] = "Text, expandable text whose %NAMES% are filled in when a program reads it, or a 32 bit number from 0 to 4294967295.",
        ["system.writeRegistry.registryData.label"] = "Data",
