        ["system.deleteRegistry.registryPath.label"] = "Key",
        ["system.deleteRegistry.registryPath.hint"] = "The key under that root, written as folders separated by backslashes, for example Software\\Vendor\\App. The root is the word above, so a path that starts with HKEY_ or with a backslash is refused.",
        ["system.deleteRegistry.valueName.label"] = "Value name",
        ["system.deleteRegistry.valueName.hint"] = "Which value inside that key. Empty means the key's own default value, the one the registry editor shows as (Default).",
        ["system.power.name"] = "Power",
        ["system.power.desc"] = "Lock the screen, sleep, sign out, restart, or shut the machine down.",
        ["system.power.powerAction.label"] = "Do what",
        ["system.power.powerAction.hint"] = "Which of the things the Start menu's power button does; locking the screen by default. Locking the screen and turning the monitor off cost nothing. Signing out, restarting and shutting down close what is open, so anything unsaved goes with it.",
        ["system.power.graceSeconds.label"] = "Warning seconds",
        ["system.power.graceSeconds.hint"] = "How much warning Windows gives before restarting or shutting down, from 0 to 600 and 0 by default: a countdown appears on screen and the shutdown can still be called off with \"Cancel a countdown\" or shutdown /a. Zero means at once. The rest of the answers ignore it.",
        ["system.showDesktop.name"] = "Show the desktop",
        ["system.showDesktop.desc"] = "Take every open window out of the way, or bring back the ones that were shrunk.",
        ["system.showDesktop.desktopAction.label"] = "Do what",
        ["system.showDesktop.desktopAction.hint"] = "Shrink every window that has a title, or bring back the ones that were shrunk; these are the two halves of what the button at the far end of the taskbar does. A macro that is about to work through the desktop, or open something over it, clears the way first.",
        ["system.volume.name"] = "Volume",
        ["system.volume.desc"] = "Read or change the volume of the speakers Windows is using.",
        ["system.volume.volumeAction.label"] = "Do what",
        ["system.volume.volumeAction.hint"] = "Whether to read the volume, set it to a level, move it up or down by a few points, or switch the sound off and on; reading it by default. This is the machine's own volume, which is not the same as the volume keys, since those turn up whichever program has the focus.",
        ["system.volume.levelPercent.label"] = "Level %",
        ["system.volume.levelPercent.hint"] = "The level to set, from 0 to 100 and 50 by default. Used by \"Set the level\".",
        ["system.volume.stepPercent.label"] = "By how much",
        ["system.volume.stepPercent.hint"] = "How far to move the volume, in points; from 1 to 100 and 5 by default. Used by \"Turn it up\" and \"Turn it down\", which never go past 0 or 100.",
        ["system.volume.returns.label"] = "Returns",
        ["system.volume.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["system.volume.return.volume.label"] = "Volume",
        ["system.volume.return.volume.hint"] = "The level the machine is left at, from 0 to 100. A step that only mutes still reports the level it is waiting at.",
        ["system.sound.name"] = "Sound",
        ["system.sound.desc"] = "Play one of the sounds this machine plays for an event, or a .wav file the macro brings with it.",
        ["system.sound.soundSource.label"] = "Where it comes from",
        ["system.sound.soundSource.hint"] = "One of the machine's own sounds, or a .wav file the macro brings with it. The machine's own sounds follow the sound scheme the user chose, so they are what they expect to hear; a file is played as the file is, which is how a macro says something no beep says.",
        ["system.sound.sound.label"] = "Play which sound",
        ["system.sound.sound.hint"] = "Which of the machine's own sounds to play; the default one by default. A macro that has finished, or gone wrong, can say so out loud without putting anything on the screen. Which sound each of these is follows the machine's own sound settings: a machine told to keep quiet plays nothing and the step is done either way, while one with no sound device at all fails the step and says why.",
        ["system.sound.soundFile.label"] = "Sound file",
        ["system.sound.soundFile.hint"] = "The .wav file to play, named where it stands; a path relative to the macros folder is read the way every other path is. Windows plays these itself, so anything else, such as an mp3 or a recording, has to be turned into one first. Reaches into variables and expressions like any other box.",
        ["system.notify.name"] = "Notification",
        ["system.notify.desc"] = "Show a notification beside the notification area.",
        ["system.notify.heading.label"] = "Title",
        ["system.notify.heading.hint"] = "The heading of the notification. Empty, which is the default, heads it with the program's own name.",
        ["system.notify.notificationText.label"] = "Message",
        ["system.notify.notificationText.hint"] = "What the notification says. Variables in it are filled in the way they are everywhere else, so a macro can report what it just did.",
        ["system.notify.notificationKind.label"] = "Kind",
        ["system.notify.notificationKind.hint"] = "How the notification is marked: an ordinary note, something worth looking at, or something that went wrong; an ordinary note by default. A machine with its notifications switched off shows nothing and the step is done either way.",
        ["system.ime.name"] = "Input Method",
        ["system.ime.desc"] = "Read or change the keyboard layout and input method of the window in front.",
        ["system.ime.imeAction.label"] = "Do what",
        ["system.ime.imeAction.hint"] = "Whether to read which keyboard layout the window in front is typing in, list the installed ones, or give it another; reading it by default. A macro that types Latin keys while a Chinese layout is in use gets Chinese candidates instead of its shortcut, so switching to the English layout first is often what makes a macro work. Turning a Chinese input method's own Chinese/English switch off is a key press rather than a setting, since Windows keeps that state inside the program being typed into, so that part is done by sending Ctrl+Space or Shift.",
        ["system.ime.layout.label"] = "Layout",
        ["system.ime.layout.hint"] = "Layout to switch to; shown only for Switch. Part of the name is enough.",
        ["system.ime.returns.label"] = "Returns",
        ["system.ime.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["system.ime.return.ime.label"] = "Input method",
        ["system.ime.return.ime.hint"] = "Which layout is in use, or the list of layouts that could be switched to.",
        ["system.ime.return.layouts.label"] = "Installed layouts",
        ["system.ime.return.layouts.hint"] = "Installed layouts, one item each, when the answer is List; empty otherwise.",
        ["system.brightness.name"] = "Brightness",
        ["system.brightness.desc"] = "Read or change how bright the screens are.",
        ["system.brightness.brightnessAction.label"] = "Do what",
        ["system.brightness.brightnessAction.hint"] = "Whether to read the brightness, set it to a level, or move it up or down a few points; reading it by default. Every screen that answers is changed together, because this talks to the screen itself over its video cable the way the brightness buttons on a monitor do, so a laptop's own panel or a screen that does not carry the setting may not answer at all.",
        ["system.brightness.levelPercent.label"] = "Level %",
        ["system.brightness.levelPercent.hint"] = "The level to set, from 0 to 100 and 50 by default. Used by \"Set the level\".",
        ["system.brightness.stepPercent.label"] = "By how much",
        ["system.brightness.stepPercent.hint"] = "How far to move the brightness, in points; from 1 to 100 and 10 by default. Used by \"Turn it up\" and \"Turn it down\", which never go past 0 or 100.",
        ["system.brightness.returns.label"] = "Returns",
        ["system.brightness.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["system.brightness.return.brightness.label"] = "Brightness",
        ["system.brightness.return.brightness.hint"] = "The brightness the screens are left at, from 0 to 100.",
