        ["window.list.return.windows.label"] = "Windows",
        ["window.list.return.windows.hint"] = "The windows that matched, each as a record of its own: the same shape window.info hands over for one window, without the part inside its border, with the fields title, handle, minimized, maximized, x and y (the middle of the window), left, top, width, height and box, plus process and class when the step is told to read them, in the order the system lists them. Two windows with the same title are two windows and get a record each. Read one field of one of them with field(get($name, 0), \"title\"), and walk them all with forEach.",
        ["window.info.name"] = "Window Info",
        ["window.info.desc"] = "Read where a window sits and how big it is into variables.",
        ["window.info.window.label"] = "Window",
        ["window.info.window.hint"] = "The window this step works on and how to recognise it again. Pick one that is open, follow the one above, or capture it with F1.",
        ["window.info.returns.label"] = "Returns",
        ["window.info.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["window.info.return.window.label"] = "Window",
        ["window.info.return.window.hint"] = "The window as one record, the shape a listing hands over for each window it finds, with the part inside its border added: title, process, class, handle, minimized, maximized, x and y (the middle of the window), left, top, width, height, box and clientBox. Read one part of it with field($name, \"left\"). box is the rectangle written as left,top,width,height, which a search region takes as it stands; it is the rectangle the window is seen at, so the border Windows keeps round it for resizing is not drawn and does not count and a maximized window is measured as it looks. clientBox is the part inside that border and under the title bar, which is where a search anchored to the window looks.",
        ["input.keyPress.name"] = "Key Press",
        ["input.keyPress.desc"] = "Press and release a key.",
        ["input.keyPress.inputMode.label"] = "Input mode",
        ["input.keyPress.inputMode.hint"] = "How this step sends input. In front uses screen coordinates and whatever window has the focus. Background posts messages at the captured window and uses coordinates from that window's client area. Driver sends through the virtual USB device and uses screen coordinates. Only background needs a window.",
        ["input.keyPress.window.label"] = "Window",
        ["input.keyPress.window.hint"] = "The window this step works on and how to recognise it again. Pick one that is open, follow the one above, or capture it with F1.",
        ["input.keyPress.key.label"] = "Key",
        ["input.keyPress.key.hint"] = "The key to press, named the way it is printed on the keyboard, for example F5, Enter or A. Take it off the keyboard drawn on screen when the spelling is not obvious.",
        ["input.keyPress.holdMs.label"] = "Hold",
        ["input.keyPress.holdMs.hint"] = "How long the key stays down, in milliseconds; 50 by default.",
        ["input.keyPress.repeat.label"] = "Repeat",
