        ["input.keySequence.name"] = "Key Sequence",
        ["input.keySequence.desc"] = "Send a run of key combinations in order, the way a game plays out a combo.",
        ["input.keySequence.inputMode.label"] = "Input mode",
        ["input.keySequence.inputMode.hint"] = "How this step sends input. In front uses screen coordinates and whatever window has the focus. Background posts messages at the captured window and uses coordinates from that window's client area. Driver sends through the virtual USB device and uses screen coordinates. Only background needs a window.",
        ["input.keySequence.window.label"] = "Window",
        ["input.keySequence.window.hint"] = "The window this step works on and how to recognise it again. Pick one that is open, follow the one above, or capture it with F1.",
        ["input.keySequence.keySequence.label"] = "The run",
        ["input.keySequence.keySequence.hint"] = "One row per combination, pressed in the order they are listed. Take the keys off the keyboard drawn on screen to be sure of the spelling: the two Ctrl keys and the two Shift keys are named apart, and the machine tells them apart. A row may say how long its own combination is held and how long to wait after it, for the one place where the beat is not the same as everywhere else; leave those empty to use the run's own.",
        ["input.keySequence.holdMs.label"] = "Hold each one for",
        ["input.keySequence.holdMs.hint"] = "How long every combination of the run stays down, in milliseconds; 50 by default. A row may say its own.",
        ["input.keySequence.gapMs.label"] = "Gap between them",
        ["input.keySequence.gapMs.hint"] = "How long the run waits between one combination and the next, in milliseconds; 120 by default. This is the beat of the combo, and it is the part a game notices: too short and the presses run into one another, too long and they stop being a combo. A row may say its own, and the give beside this box is what keeps the beat from being the same number every time a macro plays it.",
        ["input.keySequence.afterMs.label"] = "Pause afterwards",
        ["input.keySequence.afterMs.hint"] = "How long to wait after the last combination before the next step runs, in milliseconds; 0 by default.",
        ["input.keySequence.repeat.label"] = "Play the run again",
        ["input.keySequence.repeat.hint"] = "How many times the whole run is played, from 1 up; 1 by default.",
        ["input.keySequence.sequenceIntervalMs.label"] = "Between runs",
        ["input.keySequence.sequenceIntervalMs.hint"] = "How long to wait between one playing of the run and the next, in milliseconds; 0 by default.",
