        ["input.mouseScroll.direction.label"] = "Direction",
        ["input.mouseScroll.direction.hint"] = "Which way the wheel turns; down by default.",
        ["input.mouseScroll.unit.label"] = "Unit",
        ["input.mouseScroll.unit.hint"] = "What the amount below is counted in; whole notches by default. Notches are the steps a wheel normally turns in. Pixels measure the same turn more finely, with 120 pixels to a notch; an application that only looks at whole notches may ignore the smaller amounts.",
        ["input.mouseScroll.amount.label"] = "Amount",
        ["input.mouseScroll.amount.hint"] = "How far to scroll, counted in the unit above, from 1 up; 3 by default.",
        ["input.mouseScroll.smoothMs.label"] = "Smooth",
        ["input.mouseScroll.smoothMs.hint"] = "Spread the scroll over this many milliseconds instead of sending it in one jump, so an application that animates its scrolling can follow; 0, the default, sends it all at once.",
        ["input.mouseScroll.x.label"] = "X",
        ["input.mouseScroll.x.hint"] = "The column of the place to scroll at, counted from the coordinate origin above, in pixels; 0 by default. Nothing is written here while the place comes from the pointer.",
        ["input.mouseScroll.y.label"] = "Y",
        ["input.mouseScroll.y.hint"] = "The row of the place to scroll at, counted from the same origin and in the same pixels; 0 by default.",
        ["input.mouseScroll.useCursor.label"] = "At the pointer's place",
        ["input.mouseScroll.useCursor.hint"] = "With this on the step writes no coordinates and works wherever the pointer is at the time. Use it when the place is decided by where the user left the mouse; the X and Y fields are then not written and not read.",
        ["input.mouseScroll.place.label"] = "Place",
        ["input.mouseScroll.place.hint"] = "A record whose x and y say where, such as a hit or a window found earlier; x and y are the middle. Filled in, the two numbers beside it are unused.",
        ["input.mouseScroll.repeat.label"] = "Repeat",
        ["input.mouseScroll.repeat.hint"] = "How many times this step is sent in a row, from 1 up; 1 by default. How long to wait between one and the next is the interval beside it.",
        ["input.mouseScroll.intervalMs.label"] = "Interval",
        ["input.mouseScroll.intervalMs.hint"] = "How long to wait between one and the next, in milliseconds; 0, the default, sends them one after the other with no pause.",
        ["input.mouseScroll.returns.label"] = "Returns",
        ["input.mouseScroll.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["input.mouseScroll.return.screenPoint.label"] = "Screen point",
        ["input.mouseScroll.return.screenPoint.hint"] = "The place the step actually used, in screen pixels. Its basis field says screen.",
        ["input.mouseScroll.return.windowPoint.label"] = "Window point",
        ["input.mouseScroll.return.windowPoint.hint"] = "The same place counted from the target window's client-area corner. Its basis field says window.",
        ["input.mouseDrag.name"] = "Mouse Drag",
        ["input.mouseDrag.desc"] = "Press at one point, move to another and release.",
        ["input.mouseDrag.inputMode.label"] = "Input mode",
        ["input.mouseDrag.inputMode.hint"] = "How this step sends input. In front uses screen coordinates and whatever window has the focus. Background posts messages at the captured window and uses coordinates from that window's client area. Driver sends through the virtual USB device and uses screen coordinates. Only background needs a window.",
        ["input.mouseDrag.window.label"] = "Window",
        ["input.mouseDrag.window.hint"] = "The window this step works on and how to recognise it again. Pick one that is open, follow the one above, or capture it with F1.",
        ["input.mouseDrag.startX.label"] = "Start X",
        ["input.mouseDrag.startX.hint"] = "The column the drag begins at, counted from the coordinate origin above, in pixels; 0 by default. “Pick region” fills both ends in at once: the corner the rectangle was dragged from goes here.",
        ["input.mouseDrag.startY.label"] = "Start Y",
        ["input.mouseDrag.startY.hint"] = "The row the drag begins at, counted from the same origin and in the same pixels; 0 by default.",
        ["input.mouseDrag.startPlace.label"] = "Start place",
        ["input.mouseDrag.startPlace.hint"] = "A record whose x and y say where the drag starts, such as a hit or a window. Fill this in to start where an earlier step found something, instead of writing the two numbers.",
        ["input.mouseDrag.endX.label"] = "End X",
        ["input.mouseDrag.endX.hint"] = "The column the drag ends at, counted from the same origin and in the same pixels as the start; 0 by default. “Pick region” puts the corner the rectangle reached here.",
        ["input.mouseDrag.endY.label"] = "End Y",
        ["input.mouseDrag.endY.hint"] = "The row the drag ends at, counted the same way; 0 by default.",
        ["input.mouseDrag.endPlace.label"] = "End place",
        ["input.mouseDrag.endPlace.hint"] = "A record whose x and y say where the drag ends, such as a hit or a window. Fill this in to end where an earlier step found something, instead of writing the two numbers.",
        ["input.mouseDrag.button.label"] = "Button",
        ["input.mouseDrag.button.hint"] = "Which mouse button; the left one by default.",
        ["input.mouseDrag.durationMs.label"] = "Duration",
        ["input.mouseDrag.durationMs.hint"] = "How long the drag takes, in milliseconds; 300 by default. The pointer travels from one end to the other over that time.",
        ["input.mouseDrag.dragSteps.label"] = "Move steps",
        ["input.mouseDrag.dragSteps.hint"] = "Intermediate move events sent while dragging, from 1 up; 20 by default. The more of them, the more finely the pointer's path is drawn.",
        ["input.mouseDrag.style.label"] = "Movement",
        ["input.mouseDrag.style.hint"] = "How the pointer travels. A bent path bows out of the straight line; a hand-like one bows, drifts slightly and eases in and out, so the move does not look like a machine drew it. A bent path is travelled rather than jumped, so an instant move borrows 200 ms to have somewhere to bend.",
        ["input.mouseDrag.settleMs.label"] = "Hold at the end",
        ["input.mouseDrag.settleMs.hint"] = "How long the button stays down at the end of the drag before it is released, in milliseconds; the default is 0, which lets go as soon as the pointer arrives. A drop that is only answered once the thing has been held over its new place for a moment, which is how a drag onto a slot becomes a drop into that slot rather than a pass over it.",
        ["input.mouseDrag.returns.label"] = "Returns",
        ["input.mouseDrag.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["input.mouseDrag.return.screenStartPoint.label"] = "Screen start point",
        ["input.mouseDrag.return.screenStartPoint.hint"] = "The place the drag actually started, with the coordinate basis it was counted in.",
        ["input.mouseDrag.return.screenEndPoint.label"] = "Screen end point",
        ["input.mouseDrag.return.screenEndPoint.hint"] = "The place the drag actually ended, with the coordinate basis it was counted in.",
        ["input.mouseDrag.return.windowStartPoint.label"] = "Window start point",
        ["input.mouseDrag.return.windowStartPoint.hint"] = "The place the drag actually started, with the coordinate basis it was counted in.",
        ["input.mouseDrag.return.windowEndPoint.label"] = "Window end point",
        ["input.mouseDrag.return.windowEndPoint.hint"] = "The place the drag actually ended, with the coordinate basis it was counted in.",
        ["gamepad.connect.name"] = "Connect Controller",
        ["gamepad.connect.desc"] = "Put the virtual controller (an Xbox 360 pad) on the machine, which the steps after this one press the buttons of. The steps that drive a controller put it there by themselves, so this is for a game that only looks at what is connected when it starts. It is the same driver-level input as a virtual keyboard: the usbip-win2 driver has to be installed.",
        ["gamepad.button.name"] = "Controller Button",
        ["gamepad.button.desc"] = "Press a button of the virtual controller, hold it down, or let it up. The buttons are named the Xbox way whatever controller is on the machine.",
        ["gamepad.button.button.label"] = "Button",
        ["gamepad.button.button.hint"] = "The button to press, named the way it is printed on the pad; A by default.",
        ["gamepad.button.buttonMode.label"] = "Action",
        ["gamepad.button.buttonMode.hint"] = "What this step does to the button; a tap by default. A tap presses and lets go; hold and let up are for a button that has to stay down across other steps.",
        ["gamepad.button.holdMs.label"] = "Hold",
        ["gamepad.button.holdMs.hint"] = "How long the button stays down, in milliseconds; 50 by default. It only applies to a tap.",
        ["gamepad.button.repeat.label"] = "Repeat",
        ["gamepad.button.repeat.hint"] = "How many times this step is sent in a row, from 1 up; 1 by default. How long to wait between one and the next is the interval beside it.",
        ["gamepad.button.intervalMs.label"] = "Interval",
        ["gamepad.button.intervalMs.hint"] = "How long to wait between one and the next, in milliseconds; 0, the default, sends them one after the other with no pause.",
        ["gamepad.stick.name"] = "Controller Stick",
        ["gamepad.stick.desc"] = "Move a stick of the virtual controller, in whole percent from its centre.",
        ["gamepad.stick.stick.label"] = "Stick",
        ["gamepad.stick.stick.hint"] = "Which of the two sticks is pushed; the left one by default.",
        ["gamepad.stick.x.label"] = "X",
        ["gamepad.stick.x.hint"] = "How far sideways the stick is pushed, as whole percent away from its centre, from -100 to 100; 0 by default, 100 all the way right and -100 all the way left.",
        ["gamepad.stick.y.label"] = "Y",
        ["gamepad.stick.y.hint"] = "How far up or down the stick is pushed, as whole percent away from its centre, from -100 to 100; 0 by default, 100 all the way up and -100 all the way down.",
        ["gamepad.trigger.name"] = "Controller Trigger",
        ["gamepad.trigger.desc"] = "Pull a trigger of the virtual controller, or let it back off.",
        ["gamepad.trigger.trigger.label"] = "Trigger",
        ["gamepad.trigger.trigger.hint"] = "Which of the two triggers is pulled; the left one by default.",
        ["gamepad.trigger.amount.label"] = "Amount",
        ["gamepad.trigger.amount.hint"] = "How far the trigger is pulled, as whole percent, from 0 to 100; 100 by default, which is all the way down. 0 lets it back off.",
        ["gamepad.release.name"] = "Release Controller",
        ["gamepad.release.desc"] = "Let go of every button, stick and trigger of the virtual controller. A run does this by itself when it finishes; this is for a macro that wants to hand the controller back in the middle of what it is doing.",
        ["vision.capture.name"] = "Capture",
        ["vision.capture.desc"] = "Capture a screen region into an image variable.",
        ["vision.capture.anchorMode.label"] = "Recognition source",
        ["vision.capture.anchorMode.hint"] = "Where this step looks: the whole desktop, or the client area of the captured window, where a moved or resized window is still read at the same place.",
        ["vision.capture.window.label"] = "Window",
        ["vision.capture.window.hint"] = "The window this step works on and how to recognise it again. Pick one that is open, follow the one above, or capture it with F1.",
        ["vision.capture.x.label"] = "Top-left X",
        ["vision.capture.x.hint"] = "How far the region's left edge is from the left of the screen, in pixels; under a window anchor, from that window's edge. Empty starts at the edge.",
        ["vision.capture.y.label"] = "Top-left Y",
        ["vision.capture.y.hint"] = "How far the region's top edge is from the top of the screen, in pixels; under a window anchor, from that window's top edge. Empty starts at the edge.",
        ["vision.capture.width.label"] = "Width to the right",
        ["vision.capture.width.hint"] = "How wide the region is, in pixels: the distance from the left edge to the right one. Left out, it reaches the right edge of the screen. At least 1.",
        ["vision.capture.height.label"] = "Height downward",
        ["vision.capture.height.hint"] = "How tall the region is, in pixels: the distance from the top edge to the bottom one. Left out, it reaches the bottom edge of the screen. At least 1.",
        ["vision.capture.rect.label"] = "Rectangle",
        ["vision.capture.rect.hint"] = "A record whose left, top, width and height say which part of the screen, such as a hit found earlier. Filled in, the four numbers beside it are not used.",
        ["vision.capture.path.label"] = "Save to file",
        ["vision.capture.path.hint"] = "File the picture is written to, PNG either way. Empty keeps it in the variable alone, which is the default, and a file of the same name is replaced.",
        ["vision.capture.returns.label"] = "Returns",
        ["vision.capture.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["vision.capture.return.image.label"] = "Picture",
        ["vision.capture.return.image.hint"] = "The picture that was captured, ready to be searched for or written out.",
        ["vision.capture.return.place.label"] = "Place",
        ["vision.capture.return.place.hint"] = "Where the picture was taken, as one record. x and y are the middle of it, which is the point a step aims at; left and top are the corner it starts at and width and height are its size in screen pixels: the picture's own size, so a capture that ran off the edge of the screen comes back smaller than it asked for; box is the whole rectangle written as left,top,width,height, ready to be used as a search region. Read one part of it with field($name, \"left\").",
        ["vision.capture.return.window.label"] = "Source window",
        ["vision.capture.return.window.hint"] = "The window the picture was taken from, or empty when it was read straight off the screen. It answers whether a step that found nothing was looking at the right window at all.",
        ["vision.capture.return.method.label"] = "How the picture was taken",
        ["vision.capture.return.method.hint"] = "The way this step took the picture, such as graphicsCapture, gdi or printWindow; empty when it read no picture.",
        ["vision.capture.return.screenPoint.label"] = "Screen point",
        ["vision.capture.return.screenPoint.hint"] = "The place the step actually used, in screen pixels. Its basis field says screen.",
        ["vision.capture.return.windowPoint.label"] = "Window point",
        ["vision.capture.return.windowPoint.hint"] = "The same place counted from the target window's client-area corner. Its basis field says window.",
        ["vision.capture.return.path.label"] = "Saved file",
        ["vision.capture.return.path.hint"] = "The file the picture was saved to; empty when Save to was left empty.",
        ["vision.captureWindow.name"] = "Capture Window",
        ["vision.captureWindow.desc"] = "Capture a whole window, title bar and all, into an image variable.",
        ["vision.captureWindow.window.label"] = "Window",
        ["vision.captureWindow.window.hint"] = "The window this step works on and how to recognise it again. Pick one that is open, follow the one above, or capture it with F1.",
        ["vision.captureWindow.path.label"] = "Save to file",
        ["vision.captureWindow.path.hint"] = "File the picture is written to, PNG either way. Empty keeps it in the variable alone, which is the default, and a file of the same name is replaced.",
        ["vision.captureWindow.returns.label"] = "Returns",
        ["vision.captureWindow.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["vision.captureWindow.return.image.label"] = "Picture",
        ["vision.captureWindow.return.image.hint"] = "The picture that was captured, title bar and all.",
        ["vision.captureWindow.return.place.label"] = "Place",
        ["vision.captureWindow.return.place.hint"] = "Where the picture was taken, as one record. x and y are the middle of it, which is the point a step aims at; left and top are the corner it starts at and width and height are its size in screen pixels: the picture's own size, so a capture that ran off the edge of the screen comes back smaller than it asked for; box is the whole rectangle written as left,top,width,height, ready to be used as a search region. Read one part of it with field($name, \"left\").",
        ["vision.captureWindow.return.window.label"] = "Source window",
        ["vision.captureWindow.return.window.hint"] = "The window the picture was taken from, or empty when it was read straight off the screen. It answers whether a step that found nothing was looking at the right window at all.",
        ["vision.captureWindow.return.method.label"] = "How the picture was taken",
        ["vision.captureWindow.return.method.hint"] = "The way this step took the picture, such as graphicsCapture, gdi or printWindow; empty when it read no picture.",
        ["vision.captureWindow.return.screenPoint.label"] = "Screen point",
        ["vision.captureWindow.return.screenPoint.hint"] = "The middle of the captured window in screen pixels. Its basis field says screen.",
        ["vision.captureWindow.return.windowPoint.label"] = "Window point",
        ["vision.captureWindow.return.windowPoint.hint"] = "The same middle counted from the target window's client-area corner. Its basis field says window.",
        ["vision.captureWindow.return.path.label"] = "Saved file",
        ["vision.captureWindow.return.path.hint"] = "The file the picture was saved to; empty when Save to was left empty.",
        ["vision.findImage.name"] = "Find Image",
        ["vision.findImage.desc"] = "Look for a reference image on screen.",
        ["vision.findImage.anchorMode.label"] = "Recognition source",
        ["vision.findImage.anchorMode.hint"] = "Where this step looks: the whole desktop, or the client area of the captured window, where a moved or resized window is still read at the same place.",
        ["vision.findImage.window.label"] = "Window",
        ["vision.findImage.window.hint"] = "The window this step works on and how to recognise it again. Pick one that is open, follow the one above, or capture it with F1.",
        ["vision.findImage.images.label"] = "Reference pictures",
        ["vision.findImage.images.hint"] = "The pictures to look for, one row each, tried in the order listed; the first that turns up is the one the step goes with. A row is a path or a variable.",
        ["vision.findImage.region.label"] = "Search region",
        ["vision.findImage.region.hint"] = "Where to look, one row per place: four numbers, or a variable holding a picture or a rectangle. Empty reads the whole screen, which is the default.",
        ["vision.findImage.confidence.label"] = "Confidence %",
        ["vision.findImage.confidence.hint"] = "How alike the picture has to be, from 0 to 100 per cent; the default is 90. Raise it for fewer false matches, lower it when the screen differs.",
        ["vision.findImage.imageSet.label"] = "Which of the pictures",
        ["vision.findImage.imageSet.hint"] = "Which of the pictures above the step goes with: the first that turns up, the surest of them, or every one of them, which finds nothing when one is missing.",
        ["vision.findImage.detectAlgorithm.label"] = "Recognition algorithm",
        ["vision.findImage.detectAlgorithm.hint"] = "How the picture is matched: normalised, the default, cancels brightness first; pixel for pixel wants a copy; features finds another size, slower.",
        ["vision.findImage.transparentColors.label"] = "Transparent colours",
        ["vision.findImage.transparentColors.hint"] = "Pixels of the reference picture in any of these colours take no part in comparing: a flat background, or a part that keeps changing. One colour a row, written as #RRGGBB or #RGB, or as a variable that holds one; with no row at all the whole picture is compared. Each press of the colour button below adds a row.",
        ["vision.findImage.autoTransparent.label"] = "Find the transparent colour automatically",
        ["vision.findImage.autoTransparent.hint"] = "When the four corners of the reference picture (top left, top right, bottom left, bottom right) are the same colour, that colour is left out of the comparing as well, without being written down: a picture cropped from a screenshot carries the colour behind it over its corners, so the same icon is still found over another one. On by default; turn it off when that colour is part of the thing itself. The corners are compared within the tolerance below, so the default of 0 asks for four corners that are exactly the same.",
        ["vision.findImage.tolerance.label"] = "Tolerance %",
        ["vision.findImage.tolerance.hint"] = "How far a pixel may be from the transparent colour and still count as it, 0 to 100 per cent; the default is 0, which asks for the very same colour.",
        ["vision.findImage.minFeatures.label"] = "Least feature pairs",
        ["vision.findImage.minFeatures.hint"] = "Only used when the algorithm is features: how many pairs have to line up before the picture counts as found. From 1 to 500, more is stricter; the default is 6.",
        ["vision.findImage.orderBy.label"] = "Count them in",
        ["vision.findImage.orderBy.hint"] = "What order the hits are numbered in, which is what the match number counts. Left to right, top to bottom is the default and the other three directions start from another corner; this counts places rather than likeness, so the best match at the bottom right is still not the first one. Best overall: the most similar first, and a picture search weighs likeness alone because every box it finds is the reference picture's own size. Closest to a point: by the distance from each hit's middle to the point below. Closest to the middle: outwards from the middle of what was searched. Ties are settled in reading order. Shuffled: for a macro that must not always take the same one.",
        ["vision.findImage.nearX.label"] = "Point X",
        ["vision.findImage.nearX.hint"] = "Where the closest-to-a-point search is measured from. Both numbers are counted the way the search region is: screen pixels, or pixels inside the target window's client area when this step works on a window, and they follow the window when it moves. A variable or an expression may stand for either, such as the x of a hit found earlier. Both empty, 0 by default, is the top left corner of that basis.",
        ["vision.findImage.nearY.label"] = "Point Y",
        ["vision.findImage.nearY.hint"] = "Where the closest-to-a-point search is measured from. Both numbers are counted the way the search region is: screen pixels, or pixels inside the target window's client area when this step works on a window, and they follow the window when it moves. A variable or an expression may stand for either, such as the y of a hit found earlier. Both empty, 0 by default, is the top left corner of that basis.",
        ["vision.findImage.matchIndex.label"] = "Match number",
        ["vision.findImage.matchIndex.hint"] = "Which of the elements the selector finds this step uses, counted from 1; the default is 1. More than there are counts as finding nothing.",
        ["vision.findImage.returns.label"] = "Returns",
        ["vision.findImage.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["vision.findImage.return.found.label"] = "Found",
        ["vision.findImage.return.found.hint"] = "True when the thing was found; false when the look completed without finding it.",
        ["vision.findImage.return.match.label"] = "Hit",
        ["vision.findImage.return.match.hint"] = "Where it was found and everything else about it, as one record; empty when it was not there. x and y are the middle (the point this action clicks or moves to), left and top are the corner a search region counts from, width and height are its size, score is how sure the reading was, box is the whole hit written as left,top,width,height, and text is what was read where the action reads writing. Read one part of it with field($name, \"x\").",
        ["vision.findImage.return.every.label"] = "Every match",
        ["vision.findImage.return.every.hint"] = "Every hit that was found, each shaped like the record above, in the order they are counted in. Walk them with forEach or count them with count(); name one of them in a search region to look at that place next. Only written when this box is ticked.",
        ["vision.findImage.return.window.label"] = "Source window",
        ["vision.findImage.return.window.hint"] = "The window the picture was taken from, or empty when it was read straight off the screen. It answers whether a step that found nothing was looking at the right window at all.",
        ["vision.findImage.return.method.label"] = "How the picture was taken",
        ["vision.findImage.return.method.hint"] = "The way this step took the picture, such as graphicsCapture, gdi or printWindow; empty when it read no picture.",
        ["vision.findImage.return.screenPoint.label"] = "Screen point",
        ["vision.findImage.return.screenPoint.hint"] = "The place the step actually used, in screen pixels. Its basis field says screen.",
        ["vision.findImage.return.windowPoint.label"] = "Window point",
        ["vision.findImage.return.windowPoint.hint"] = "The same place counted from the target window's client-area corner. Its basis field says window.",
        ["vision.waitImage.name"] = "Wait Image",
        ["vision.waitImage.desc"] = "Wait until a reference image appears on screen, for as long as the step's own timeout allows; running out of it fails the step.",
        ["vision.waitImage.anchorMode.label"] = "Recognition source",
        ["vision.waitImage.anchorMode.hint"] = "Where this step looks: the whole desktop, or the client area of the captured window, where a moved or resized window is still read at the same place.",
        ["vision.waitImage.window.label"] = "Window",
        ["vision.waitImage.window.hint"] = "The window this step works on and how to recognise it again. Pick one that is open, follow the one above, or capture it with F1.",
        ["vision.waitImage.images.label"] = "Reference pictures",
        ["vision.waitImage.images.hint"] = "The pictures to wait for, one row each, tried in the order they are listed. A row is a file path or the variable a Capture step saved ($shot).",
        ["vision.waitImage.region.label"] = "Search region",
        ["vision.waitImage.region.hint"] = "Where to look, one row per place: four numbers, or a variable holding a picture or a rectangle. Empty reads the whole screen, which is the default.",
        ["vision.waitImage.confidence.label"] = "Confidence %",
        ["vision.waitImage.confidence.hint"] = "How alike the picture has to be, from 0 to 100 per cent; the default is 90. Raise it for fewer false matches, lower it when the screen differs.",
        ["vision.waitImage.imageSet.label"] = "Which of the pictures",
        ["vision.waitImage.imageSet.hint"] = "Which of the pictures above the step goes with: the first that turns up, the surest of them, or every one of them, which finds nothing when one is missing.",
        ["vision.waitImage.detectAlgorithm.label"] = "Recognition algorithm",
        ["vision.waitImage.detectAlgorithm.hint"] = "How the picture is matched: normalised, the default, cancels brightness first; pixel for pixel wants a copy; features finds another size, slower.",
        ["vision.waitImage.transparentColors.label"] = "Transparent colours",
        ["vision.waitImage.transparentColors.hint"] = "Pixels of the reference picture in any of these colours take no part in comparing: a flat background, or a part that keeps changing. One colour a row, written as #RRGGBB or #RGB, or as a variable that holds one; with no row at all the whole picture is compared. Each press of the colour button below adds a row.",
        ["vision.waitImage.autoTransparent.label"] = "Find the transparent colour automatically",
        ["vision.waitImage.autoTransparent.hint"] = "When the four corners of the reference picture (top left, top right, bottom left, bottom right) are the same colour, that colour is left out of the comparing as well, without being written down: a picture cropped from a screenshot carries the colour behind it over its corners, so the same icon is still found over another one. On by default; turn it off when that colour is part of the thing itself. The corners are compared within the tolerance below, so the default of 0 asks for four corners that are exactly the same.",
        ["vision.waitImage.tolerance.label"] = "Tolerance %",
        ["vision.waitImage.tolerance.hint"] = "How far a pixel may be from the transparent colour and still count as it, 0 to 100 per cent; the default is 0, which asks for the very same colour.",
        ["vision.waitImage.minFeatures.label"] = "Least feature pairs",
        ["vision.waitImage.minFeatures.hint"] = "Only used when the algorithm is features: how many pairs have to line up before the picture counts as found. From 1 to 500, more is stricter; the default is 6.",
        ["vision.waitImage.orderBy.label"] = "Count them in",
        ["vision.waitImage.orderBy.hint"] = "What order the hits are numbered in, which is what the match number counts. Left to right, top to bottom is the default and the other three directions start from another corner; this counts places rather than likeness, so the best match at the bottom right is still not the first one. Best overall: the most similar first, and a picture search weighs likeness alone because every box it finds is the reference picture's own size. Closest to a point: by the distance from each hit's middle to the point below. Closest to the middle: outwards from the middle of what was searched. Ties are settled in reading order. Shuffled: for a macro that must not always take the same one.",
        ["vision.waitImage.nearX.label"] = "Point X",
        ["vision.waitImage.nearX.hint"] = "Where the closest-to-a-point search is measured from. Both numbers are counted the way the search region is: screen pixels, or pixels inside the target window's client area when this step works on a window, and they follow the window when it moves. A variable or an expression may stand for either, such as the x of a hit found earlier. Both empty, 0 by default, is the top left corner of that basis.",
        ["vision.waitImage.nearY.label"] = "Point Y",
        ["vision.waitImage.nearY.hint"] = "Where the closest-to-a-point search is measured from. Both numbers are counted the way the search region is: screen pixels, or pixels inside the target window's client area when this step works on a window, and they follow the window when it moves. A variable or an expression may stand for either, such as the y of a hit found earlier. Both empty, 0 by default, is the top left corner of that basis.",
        ["vision.waitImage.matchIndex.label"] = "Match number",
        ["vision.waitImage.matchIndex.hint"] = "Which of the elements the selector finds this step uses, counted from 1; the default is 1. More than there are counts as finding nothing.",
        ["vision.waitImage.returns.label"] = "Returns",
        ["vision.waitImage.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["vision.waitImage.return.match.label"] = "Hit",
        ["vision.waitImage.return.match.hint"] = "Where it was found and everything else about it, as one record; empty when it was not there. x and y are the middle (the point this action clicks or moves to), left and top are the corner a search region counts from, width and height are its size, score is how sure the reading was, box is the whole hit written as left,top,width,height, and text is what was read where the action reads writing. Read one part of it with field($name, \"x\").",
        ["vision.waitImage.return.every.label"] = "Every match",
        ["vision.waitImage.return.every.hint"] = "Every hit that was found, each shaped like the record above, in the order they are counted in. Walk them with forEach or count them with count(); name one of them in a search region to look at that place next. Only written when this box is ticked.",
        ["vision.waitImage.return.window.label"] = "Source window",
        ["vision.waitImage.return.window.hint"] = "The window the picture was taken from, or empty when it was read straight off the screen. It answers whether a step that found nothing was looking at the right window at all.",
        ["vision.waitImage.return.method.label"] = "How the picture was taken",
        ["vision.waitImage.return.method.hint"] = "The way this step took the picture, such as graphicsCapture, gdi or printWindow; empty when it read no picture.",
        ["vision.waitImage.return.screenPoint.label"] = "Screen point",
        ["vision.waitImage.return.screenPoint.hint"] = "The place the step actually used, in screen pixels. Its basis field says screen.",
        ["vision.waitImage.return.windowPoint.label"] = "Window point",
        ["vision.waitImage.return.windowPoint.hint"] = "The same place counted from the target window's client-area corner. Its basis field says window.",
        ["vision.clickImage.name"] = "Click Image",
        ["vision.clickImage.desc"] = "Find a reference image on screen and click it, waiting for as long as the step's own timeout allows; running out of it fails the step.",
        ["vision.clickImage.anchorMode.label"] = "Recognition source",
        ["vision.clickImage.anchorMode.hint"] = "Where this step looks: the whole desktop, or the client area of the captured window, where a moved or resized window is still read at the same place.",
        ["vision.clickImage.window.label"] = "Window",
        ["vision.clickImage.window.hint"] = "The window this step works on and how to recognise it again. Pick one that is open, follow the one above, or capture it with F1.",
        ["vision.clickImage.images.label"] = "Reference pictures",
        ["vision.clickImage.images.hint"] = "The pictures to look for, one row each, tried in the order they are listed; the first one that turns up is the one that gets clicked.",
        ["vision.clickImage.region.label"] = "Search region",
        ["vision.clickImage.region.hint"] = "Where to look, one row per place: four numbers, or a variable holding a picture or a rectangle. Empty reads the whole screen, which is the default.",
        ["vision.clickImage.confidence.label"] = "Confidence %",
        ["vision.clickImage.confidence.hint"] = "How alike the picture has to be, from 0 to 100 per cent; the default is 90. Raise it for fewer false matches, lower it when the screen differs.",
        ["vision.clickImage.imageSet.label"] = "Which of the pictures",
        ["vision.clickImage.imageSet.hint"] = "Which of the pictures above the step goes with: the first that turns up, the surest of them, or every one of them, which finds nothing when one is missing.",
        ["vision.clickImage.button.label"] = "Button",
        ["vision.clickImage.button.hint"] = "Which mouse button; the left one by default.",
        ["vision.clickImage.offsetX.label"] = "Offset X",
        ["vision.clickImage.offsetX.hint"] = "Pixels added to the middle of the match before clicking. 0, the default, clicks the middle.",
        ["vision.clickImage.offsetY.label"] = "Offset Y",
        ["vision.clickImage.offsetY.hint"] = "Pixels added to the middle of the match before clicking, downwards for a positive number; 0, the default, clicks the middle.",
        ["vision.clickImage.detectAlgorithm.label"] = "Recognition algorithm",
        ["vision.clickImage.detectAlgorithm.hint"] = "How the picture is matched: normalised, the default, cancels brightness first; pixel for pixel wants a copy; features finds another size, slower.",
        ["vision.clickImage.transparentColors.label"] = "Transparent colours",
        ["vision.clickImage.transparentColors.hint"] = "Pixels of the reference picture in any of these colours take no part in comparing: a flat background, or a part that keeps changing. One colour a row, written as #RRGGBB or #RGB, or as a variable that holds one; with no row at all the whole picture is compared. Each press of the colour button below adds a row.",
        ["vision.clickImage.autoTransparent.label"] = "Find the transparent colour automatically",
        ["vision.clickImage.autoTransparent.hint"] = "When the four corners of the reference picture (top left, top right, bottom left, bottom right) are the same colour, that colour is left out of the comparing as well, without being written down: a picture cropped from a screenshot carries the colour behind it over its corners, so the same icon is still found over another one. On by default; turn it off when that colour is part of the thing itself. The corners are compared within the tolerance below, so the default of 0 asks for four corners that are exactly the same.",
        ["vision.clickImage.tolerance.label"] = "Tolerance %",
        ["vision.clickImage.tolerance.hint"] = "How far a pixel may be from the transparent colour and still count as it, 0 to 100 per cent; the default is 0, which asks for the very same colour.",
        ["vision.clickImage.minFeatures.label"] = "Least feature pairs",
        ["vision.clickImage.minFeatures.hint"] = "Only used when the algorithm is features: how many pairs have to line up before the picture counts as found. From 1 to 500, more is stricter; the default is 6.",
        ["vision.clickImage.orderBy.label"] = "Count them in",
        ["vision.clickImage.orderBy.hint"] = "What order the hits are numbered in, which is what the match number counts. Left to right, top to bottom is the default and the other three directions start from another corner; this counts places rather than likeness, so the best match at the bottom right is still not the first one. Best overall: the most similar first, and a picture search weighs likeness alone because every box it finds is the reference picture's own size. Closest to a point: by the distance from each hit's middle to the point below. Closest to the middle: outwards from the middle of what was searched. Ties are settled in reading order. Shuffled: for a macro that must not always take the same one.",
        ["vision.clickImage.nearX.label"] = "Point X",
        ["vision.clickImage.nearX.hint"] = "Where the closest-to-a-point search is measured from. Both numbers are counted the way the search region is: screen pixels, or pixels inside the target window's client area when this step works on a window, and they follow the window when it moves. A variable or an expression may stand for either, such as the x of a hit found earlier. Both empty, 0 by default, is the top left corner of that basis.",
        ["vision.clickImage.nearY.label"] = "Point Y",
        ["vision.clickImage.nearY.hint"] = "Where the closest-to-a-point search is measured from. Both numbers are counted the way the search region is: screen pixels, or pixels inside the target window's client area when this step works on a window, and they follow the window when it moves. A variable or an expression may stand for either, such as the y of a hit found earlier. Both empty, 0 by default, is the top left corner of that basis.",
        ["vision.clickImage.matchIndex.label"] = "Match number",
        ["vision.clickImage.matchIndex.hint"] = "Which of the elements the selector finds this step uses, counted from 1; the default is 1. More than there are counts as finding nothing.",
        ["vision.clickImage.variance.label"] = "Aim within",
        ["vision.clickImage.variance.hint"] = "How far a click may land from the place it aimed at, in pixels; the default is 0, which lands on it. Given a number, each click is placed at random.",
        ["vision.clickImage.confirmMs.label"] = "Confirm after",
        ["vision.clickImage.confirmMs.hint"] = "How long to wait before looking a second time, in milliseconds; the default is 0, which acts at once. Still there it acts; gone, it counts as not found.",
        ["vision.clickImage.returns.label"] = "Returns",
        ["vision.clickImage.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["vision.clickImage.return.match.label"] = "Hit",
        ["vision.clickImage.return.match.hint"] = "Where it was found and everything else about it, as one record; empty when it was not there. x and y are the middle (the point this action clicks or moves to), left and top are the corner a search region counts from, width and height are its size, score is how sure the reading was, box is the whole hit written as left,top,width,height, and text is what was read where the action reads writing. Read one part of it with field($name, \"x\").",
