        ["browser.press.keyChord.label"] = "Key",
        ["browser.press.keyChord.hint"] = "Which key to send: a name the keyboard picker offers, or several joined with + for one chord (Ctrl+S). A name it does not have is refused.",
        ["browser.press.matchIndex.label"] = "Match number",
        ["browser.press.matchIndex.hint"] = "Which of the elements the selector finds this step uses, counted from 1; the default is 1. More than there are counts as finding nothing.",
        ["browser.waitFor.name"] = "Wait for Web Element",
