        ["browser.waitFor.elementState.label"] = "Wait for it to",
        ["browser.waitFor.elementState.hint"] = "Which state to wait for: visible, not visible, on the page whether or not it takes up room, or off the page because it has been taken away.",
        ["browser.waitFor.matchIndex.label"] = "Match number",
        ["browser.waitFor.matchIndex.hint"] = "Which of the elements the selector finds this step uses, counted from 1; the default is 1. More than there are counts as finding nothing.",
        ["browser.waitForUrl.name"] = "Wait For Address",
        ["browser.waitForUrl.desc"] = "Waits for the page to be at an address.",
        ["browser.waitForUrl.urlMatch.label"] = "Address holds",
        ["browser.waitForUrl.urlMatch.hint"] = "What the address has to hold before the step is done, read as one value. Worth waiting for after a click that goes to another page.",
        ["browser.waitForUrl.urlHow.label"] = "Compare",
        ["browser.waitForUrl.urlHow.hint"] = "How the address is compared with the text above: contained, starting, ending, exactly, or as a regular expression; contained by default.",
        ["browser.waitForLoad.name"] = "Wait for Page Load",
        ["browser.waitForLoad.desc"] = "Waits for the page to finish loading.",
        ["browser.waitForLoad.loadState.label"] = "Wait for",
        ["browser.waitForLoad.loadState.hint"] = "Which moment of loading to wait for: finished, the default, the document ready before pictures and stylesheets, or the network falling quiet.",
        ["browser.scroll.name"] = "Scroll The Page",
        ["browser.scroll.desc"] = "Moves the page so that what is below the fold comes into view.",
        ["browser.scroll.pageSelector.label"] = "Selector",
        ["browser.scroll.pageSelector.hint"] = "One selector to a line, tried in that order; the first line that finds the element is used, so a second survives a redesign. Reads like CSS, or as text=Sign in.",
        ["browser.scroll.narrow.label"] = "Condition",
        ["browser.scroll.narrow.hint"] = "Conditions the element must also meet besides the selector, one per row, all holding at once: the text it shows, an element it holds, or visible.",
        ["browser.scroll.scrollHow.label"] = "Scroll",
        ["browser.scroll.scrollHow.hint"] = "How the page is moved: one screen further down, the default, an element brought into view, to the bottom of what the page has, or back to the top.",
        ["browser.scroll.matchIndex.label"] = "Match number",
        ["browser.scroll.matchIndex.hint"] = "Which of the elements the selector finds this step uses, counted from 1; the default is 1. More than there are counts as finding nothing.",
        ["browser.download.name"] = "Download Web File",
        ["browser.download.desc"] = "Saves the next file the page hands over.",
        ["browser.download.pageSelector.label"] = "Selector",
        ["browser.download.pageSelector.hint"] = "One selector to a line, tried in that order; the first line that finds the element is used, so a second survives a redesign. Reads like CSS, or as text=Sign in.",
        ["browser.download.narrow.label"] = "Condition",
        ["browser.download.narrow.hint"] = "Conditions the element must also meet besides the selector, one per row, all holding at once: the text it shows, an element it holds, or visible.",
        ["browser.download.folder.label"] = "Folder",
        ["browser.download.folder.hint"] = "Which folder to save the file into; leaving it out is the folder the macro file is in, read as one value. A file of the same name already there is replaced.",
        ["browser.download.matchIndex.label"] = "Match number",
        ["browser.download.matchIndex.hint"] = "Which of the elements the selector finds this step uses, counted from 1; the default is 1. More than there are counts as finding nothing.",
        ["browser.download.returns.label"] = "Returns",
        ["browser.download.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["browser.download.return.path.label"] = "Saved as",
        ["browser.download.return.path.hint"] = "Where the file was saved, written the way a path is read: a later step given this saves beside it.",
        ["browser.download.return.name.label"] = "File name",
        ["browser.download.return.name.hint"] = "What the page called the file.",
        ["browser.dialog.name"] = "Answer Web Dialog",
        ["browser.dialog.desc"] = "Answers the next dialog the page puts up, around the steps that raise it.",
        ["browser.dialog.dialogHow.label"] = "Answer it by",
        ["browser.dialog.dialogHow.hint"] = "Whether the dialog is accepted or dismissed. Accepting carries the writing below. Any dialog after the first inside the box is dismissed.",
        ["browser.dialog.dialogText.label"] = "Text to type",
        ["browser.dialog.dialogText.hint"] = "The writing to put into a dialog that asks for some, read as one value. Left out, the default, is an empty answer.",
        ["browser.dialog.body.label"] = "Steps that raise it",
        ["browser.dialog.body.hint"] = "The steps that make the dialog appear, such as the click that asks: an unanswered dialog stops the page until it is answered.",
        ["browser.dialog.returns.label"] = "Returns",
        ["browser.dialog.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["browser.dialog.return.message.label"] = "Message",
        ["browser.dialog.return.message.hint"] = "What the dialog that was answered said, such as what a page asks before going on.",
        ["browser.evaluate.name"] = "Run Web Script",
        ["browser.evaluate.desc"] = "Run a piece of JavaScript in the page and take back what it returns. A string comes back as it is; a number, flag, list or record comes back as JSON and can be handed straight to the next step, such as Go to.",
        ["browser.evaluate.script.label"] = "Script",
        ["browser.evaluate.script.hint"] = "JavaScript the page runs, written as a function such as () => document.title. What return hands back is the result. {{variable}} is filled in first.",
        ["browser.evaluate.returns.label"] = "Returns",
        ["browser.evaluate.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["browser.evaluate.return.result.label"] = "Result",
        ["browser.evaluate.return.result.hint"] = "What the script returned, written as JSON: writing comes back in quotes, a number as a number, and a record or a list as the page handed it over, read one field of it with field(). A script that returns nothing leaves this empty.",
        ["browser.upload.name"] = "Upload Web File",
        ["browser.upload.desc"] = "Hands files to a file input on the page.",
        ["browser.upload.pageSelector.label"] = "Selector",
        ["browser.upload.pageSelector.hint"] = "One selector to a line, tried in that order; the first line that finds the element is used, so a second survives a redesign. Reads like CSS, or as text=Sign in.",
        ["browser.upload.narrow.label"] = "Condition",
        ["browser.upload.narrow.hint"] = "Conditions the element must also meet besides the selector, one per row, all holding at once: the text it shows, an element it holds, or visible.",
        ["browser.upload.uploadFiles.label"] = "Files",
        ["browser.upload.uploadFiles.hint"] = "One path to a file, one to a line, so a blank line is skipped. A relative path is read from the macro's folder. This is how a page is given files.",
        ["browser.upload.matchIndex.label"] = "Match number",
        ["browser.upload.matchIndex.hint"] = "Which of the elements the selector finds this step uses, counted from 1; the default is 1. More than there are counts as finding nothing.",
        ["browser.switchTab.name"] = "Switch Tab",
        ["browser.switchTab.desc"] = "Moves to another tab of the browser that is open.",
        ["browser.switchTab.tabHow.label"] = "Which tab",
        ["browser.switchTab.tabHow.hint"] = "Which tab the steps after this one work on: the newest one, the default, which is the tab a click leaves behind when it opens one, or the one already in front.",
        ["browser.switchTab.tabIndex.label"] = "Tab number",
        ["browser.switchTab.tabIndex.hint"] = "Which tab, counted from the left of the tab strip starting at 1. Used with \"by number\" above. From 1 to 50; 1 by default.",
        ["browser.switchTab.tabMatch.label"] = "Title or address holds",
        ["browser.switchTab.tabMatch.hint"] = "The text the tab's title (or address) has to contain. Used with \"by title\" and \"by address\" above.",
        ["browser.closeTab.name"] = "Close Tab",
        ["browser.closeTab.desc"] = "Closes the tab the browser is on, and moves to another one.",
        ["browser.close.name"] = "Close Browser",
        ["browser.close.desc"] = "Closes the browser the macro opened.",
        ["script.run.name"] = "Run Script",
        ["script.run.desc"] = "Run a command, a batch file, a PowerShell or an AutoHotkey script, or a program of your own choosing.",
        ["script.run.kind.label"] = "Kind of script",
        ["script.run.kind.hint"] = "What this step hands the script to. The three command kinds write the text out as a batch file and run it with cmd.exe: the first one leaves its window open afterwards so what it printed can be read, the second closes the window when the command is done, and the third shows no window at all. The two file kinds and the PowerShell and AutoHotkey kinds run without a window; a program of your own choosing is for anything else the machine has. PowerShell by default.",
        ["script.run.scriptSource.label"] = "Run",
        ["script.run.scriptSource.hint"] = "What this step runs: the script written below, or a file that is already on this machine. A file is run where it lies, so what it reads beside itself, what it includes and what its own folder is all stay what its author wrote, and nothing takes the place of {{name}} in it. The script written below by default.",
        ["script.run.script.label"] = "Script",
        ["script.run.script.hint"] = "The script itself, told to the program named above. {{name}} is replaced by what the variable name holds before the script runs, which is how a macro value gets in; everything the script prints comes back in the output result where the kind of script can be read that way.",
        ["script.run.scriptFile.label"] = "Script file",
        ["script.run.scriptFile.hint"] = "The script to run, named where it stands; the kind of script above is what runs it, and the file's own ending is not looked at. Point this at a script somebody else keeps up to date, or one too long to keep in a step. A path on its own is taken to be inside the macros folder.",
        ["script.run.encoding.label"] = "Script file encoding",
        ["script.run.encoding.hint"] = "How the copy of the script handed to the program is written. Left to decide for itself, a batch file or a command gets this machine's own code page, PowerShell and AutoHotkey get a byte-order mark, and a program of your own choosing gets plain UTF-8, which is what each of them reads correctly. A program that reads the system code page instead, cscript for one, needs GBK to read Chinese text. Reading it as the kind of script expects is the default.",
        ["script.run.sendsInput.label"] = "The script sends keyboard or mouse input",
        ["script.run.sendsInput.hint"] = "Turn this on when the script types or clicks by itself. It is a declaration for the design-time warning: WhaleGenie cannot see input a script sends directly, so the input door cannot hold it back. Off by default.",
        ["script.run.interpreter.label"] = "Interpreter command",
        ["script.run.interpreter.hint"] = "The program that runs the script, with any flags of its own in front, used with \"another program\" above. The script's path goes after it, the way it would be typed on a command line. A path with spaces in it goes in quotes.",
        ["script.run.extension.label"] = "Script file ending",
        ["script.run.extension.hint"] = "The file name ending that program reads, such as .csx for dotnet-script or .vbs for cscript. Only used with \"another program\" above.",
        ["script.run.scriptArguments.label"] = "Arguments",
        ["script.run.scriptArguments.hint"] = "Extra arguments for the script's command line. {{name}} is filled in here as well. Empty, which is the default, passes nothing.",
        ["script.run.folder.label"] = "Working folder",
        ["script.run.folder.hint"] = "The folder the script runs in. Empty, which is the default, runs it in the macros folder, or wherever WhaleGenie is when that folder is not there yet.",
        ["script.run.returns.label"] = "Returns",
        ["script.run.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["script.run.return.output.label"] = "Output",
        ["script.run.return.output.hint"] = "What the script printed, without the blank lines around it. Only the kinds that run without a window can be read this way; a command run in a window prints into that window and leaves this empty.",
        ["script.run.return.error.label"] = "Error message",
        ["script.run.return.error.hint"] = "What the script said on its error output, or the message the interpreter itself failed with. Empty when the script ended well, and empty for a script that ran in a window, which has nowhere to send it.",
        ["script.run.return.success.label"] = "Ran without error",
        ["script.run.return.success.hint"] = "True when the script ended with exit code 0, false when it did not. A script that ended with anything else fails the step as well, so this is read after the failure rule let the macro carry on.",
        ["script.run.return.exitCode.label"] = "Exit code",
        ["script.run.return.exitCode.hint"] = "The code the script ended with; 0 usually means it went well. Kept apart from the message because a script often means something by the code it chose: a 3 can say \"nothing to do today\" without being a failure, and a macro can branch on it once the failure rule has let it carry on.",
        ["script.python.name"] = "Run Python Script",
        ["script.python.desc"] = "Run a Python script, with the macro's values and steps in reach of it while it runs.",
        ["script.python.script.label"] = "Script",
        ["script.python.script.hint"] = "The script itself. Everything it prints goes into the run log, and the values of the macro are in reach of it while it runs: WhaleGenie.GetProperty(\"name\") reads one, SetProperty(\"name\", value) writes one, StepExecute(\"a7k2\") runs one step of this macro, Print(text) writes a line to the run log, and SetResult(value) hands back what this step should leave behind.",
        ["script.python.sendsInput.label"] = "The script sends keyboard or mouse input",
        ["script.python.sendsInput.hint"] = "Turn this on when the script types or clicks by itself. It is a declaration for the design-time warning: WhaleGenie cannot see input a script sends directly, so the input door cannot hold it back. Off by default.",
        ["script.python.python.label"] = "Python command",
        ["script.python.python.hint"] = "The Python this step runs with, with any flags of its own in front. A path with spaces in it goes in quotes. Empty, which is the default, uses \"python\" from this machine's search path.",
        ["script.python.scriptArguments.label"] = "Arguments",
        ["script.python.scriptArguments.hint"] = "Extra arguments for the script's command line, which the script finds in sys.argv the way a program started from a command line does. Empty, which is the default, passes nothing.",
        ["script.python.folder.label"] = "Working folder",
        ["script.python.folder.hint"] = "The folder the script runs in. Empty, which is the default, runs it in the macros folder, or wherever WhaleGenie is when that folder is not there yet.",
        ["script.python.returns.label"] = "Returns",
        ["script.python.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["script.python.return.value.label"] = "Result",
        ["script.python.return.value.hint"] = "What the script handed back with WhaleGenie.SetResult, as it is: a number, a piece of writing, true or false, a list, or a record with named fields. Empty when the script handed nothing back.",
        ["script.python.return.error.label"] = "Error message",
        ["script.python.return.error.hint"] = "What the script said on its error output, which is where a Python mistake is reported, with the line it was written on. Empty when it ran to the end without one.",
        ["script.python.return.success.label"] = "Ran without error",
        ["script.python.return.success.hint"] = "True when the script ran to the end without a mistake, false when it did not. A script that ended badly fails the step as well, so this is read after the failure rule let the macro carry on.",
        ["script.python.return.exitCode.label"] = "Exit code",
        ["script.python.return.exitCode.hint"] = "The code the script ended with; 0 usually means it went well. Kept apart from the message because a script often means something by the code it chose: a 3 can say \"nothing to do today\" without being a failure, and a macro can branch on it once the failure rule has let it carry on.",
        ["script.pip.name"] = "Install PIP Packages",
        ["script.pip.desc"] = "Check which Python packages are there and download the ones that are not, so a Python script can import them.",
        ["script.pip.packages.label"] = "Packages",
        ["script.pip.packages.hint"] = "The packages a Python script needs, one to a line, written the way pip writes them: a name, or a name with the version it has to be after two equals signs. A line that begins with a hash is left out. Packages are installed into a folder of WhaleGenie's own rather than into this machine's Python, and every Python script step can import what is in it.",
        ["script.pip.python.label"] = "Python command",
        ["script.pip.python.hint"] = "The Python whose pip downloads the packages, with any flags of its own in front. Empty, which is the default, uses \"python\" from this machine's search path.",
        ["script.pip.returns.label"] = "Returns",
        ["script.pip.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["script.pip.return.packages.label"] = "Packages installed",
        ["script.pip.return.packages.hint"] = "The packages this run of the step put there, one to an item. Empty when everything asked for was already installed.",
        ["script.pip.return.error.label"] = "Error message",
        ["script.pip.return.error.hint"] = "What pip said on its error output when it could not do what was asked. Empty when it went well.",
        ["script.pip.return.success.label"] = "Ran without error",
        ["script.pip.return.success.hint"] = "True when pip ended well, false when it did not. A run that ended badly fails the step as well.",
        ["script.pip.return.exitCode.label"] = "Exit code",
        ["script.pip.return.exitCode.hint"] = "The code the script ended with; 0 usually means it went well. Kept apart from the message because a script often means something by the code it chose: a 3 can say \"nothing to do today\" without being a failure, and a macro can branch on it once the failure rule has let it carry on.",
        ["script.csharp.name"] = "Run C# Script",
        ["script.csharp.desc"] = "Compile a C# script and run it, with the macro's values and steps in reach of it while it runs.",
        ["script.csharp.script.label"] = "Script",
        ["script.csharp.script.hint"] = "The script itself. It is compiled and run in a process of this program's own, so nothing it does to itself reaches the macro, and the macro is in reach of it while it runs: the name WhaleGenie is the macro. GetProperty(\"name\") reads one of its values, SetProperty(\"name\", value) writes one, StepExecute(\"a7k2\") runs one step of it, SetResult(value) hands back what this step should leave behind, and everything written with Console.WriteLine goes into the run log.",
        ["script.csharp.sendsInput.label"] = "The script sends keyboard or mouse input",
        ["script.csharp.sendsInput.hint"] = "Turn this on when the script types or clicks by itself. It is a declaration for the design-time warning: WhaleGenie cannot see input a script sends directly, so the input door cannot hold it back. Off by default.",
        ["script.csharp.scriptArguments.label"] = "Arguments",
        ["script.csharp.scriptArguments.hint"] = "Extra arguments for the script's command line, which the entry point finds in the array it is called with. Empty, which is the default, passes nothing.",
        ["script.csharp.folder.label"] = "Working folder",
        ["script.csharp.folder.hint"] = "The folder the script runs in. Empty, which is the default, runs it in the macros folder, or wherever WhaleGenie is when that folder is not there yet.",
        ["script.csharp.returns.label"] = "Returns",
        ["script.csharp.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["script.csharp.return.value.label"] = "Result",
        ["script.csharp.return.value.hint"] = "What the script handed back with WhaleGenie.SetResult, as it is: a number, a piece of writing, true or false, a list, or a record with named fields. Empty when the script handed nothing back.",
        ["script.csharp.return.error.label"] = "Error message",
        ["script.csharp.return.error.hint"] = "What the compiler said when the script will not compile, or the mistake it made while it ran, with the line it was written on. Empty when it ran to the end without one.",
        ["script.csharp.return.success.label"] = "Ran without error",
        ["script.csharp.return.success.hint"] = "True when the script compiled and ran to the end without a mistake, false when it did not. A script that ended badly fails the step as well, so this is read after the failure rule let the macro carry on.",
        ["script.csharp.return.exitCode.label"] = "Exit code",
        ["script.csharp.return.exitCode.hint"] = "The code the script ended with; 0 usually means it went well. Kept apart from the message because a script often means something by the code it chose: a 3 can say \"nothing to do today\" without being a failure, and a macro can branch on it once the failure rule has let it carry on.",
        ["script.ahk.name"] = "Run AutoHotkey Script",
        ["script.ahk.desc"] = "Run an AutoHotkey script, with the macro's values and steps in reach of it while it runs.",
        ["script.ahk.script.label"] = "Script",
        ["script.ahk.script.hint"] = "The script itself, written for AutoHotkey version 2. Everything it prints goes into the run log, and the macro is in reach of it while it runs: GetProperty(\"name\") reads one of its values, SetProperty(\"name\", value) writes one, StepExecute(\"a7k2\") runs one step of this macro, Print(text) writes a line to the run log, and SetResult(value) hands back what this step should leave behind.",
        ["script.ahk.sendsInput.label"] = "The script sends keyboard or mouse input",
        ["script.ahk.sendsInput.hint"] = "Turn this on when the script types or clicks by itself. It is a declaration for the design-time warning: WhaleGenie cannot see input a script sends directly, so the input door cannot hold it back. Off by default.",
        ["script.ahk.ahk.label"] = "AutoHotkey command",
        ["script.ahk.ahk.hint"] = "The AutoHotkey this step runs with, with any flags of its own in front. A path with spaces in it goes in quotes. Empty, which is the default, uses the AutoHotkey this machine has.",
        ["script.ahk.scriptArguments.label"] = "Arguments",
        ["script.ahk.scriptArguments.hint"] = "Extra arguments for the script's command line, which the script finds in A_Args the way a program started from a command line does. Empty, which is the default, passes nothing.",
        ["script.ahk.folder.label"] = "Working folder",
        ["script.ahk.folder.hint"] = "The folder the script runs in. Empty, which is the default, runs it in the macros folder, or wherever WhaleGenie is when that folder is not there yet.",
        ["script.ahk.returns.label"] = "Returns",
        ["script.ahk.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["script.ahk.return.value.label"] = "Result",
        ["script.ahk.return.value.hint"] = "What the script handed back with SetResult, as it is: a number, a piece of writing, true or false, a list, or a record with named fields. Empty when the script handed nothing back.",
        ["script.ahk.return.error.label"] = "Error message",
        ["script.ahk.return.error.hint"] = "What the script said on its error output, which is where AutoHotkey reports a mistake of its own, with the line it was written on. Empty when it ran to the end without one.",
        ["script.ahk.return.success.label"] = "Ran without error",
        ["script.ahk.return.success.hint"] = "True when the script ran to the end without a mistake, false when it did not. A script that ended badly fails the step as well, so this is read after the failure rule let the macro carry on.",
        ["script.ahk.return.exitCode.label"] = "Exit code",
        ["script.ahk.return.exitCode.hint"] = "The code the script ended with; 0 usually means it went well. Kept apart from the message because a script often means something by the code it chose: a 3 can say \"nothing to do today\" without being a failure, and a macro can branch on it once the failure rule has let it carry on.",
        ["script.nuget.name"] = "Download NuGet Packages",
        ["script.nuget.desc"] = "Check which NuGet packages are there and download the ones that are not, with everything they need, so a C# script can be compiled against them.",
        ["script.nuget.packages.label"] = "Packages",
        ["script.nuget.packages.hint"] = "The packages a C# script needs, one to a line: a name, or a name and the version it has to be, one space apart. A name without a version takes the newest stable one. A line that begins with a hash is left out. Packages are downloaded into a folder of WhaleGenie's own, with everything they depend on, and every C# script is compiled against what is in it.",
        ["script.nuget.returns.label"] = "Returns",
        ["script.nuget.returns.hint"] = "Tick the results this step hands over. Each ticked one becomes a variable later steps read. Nothing ticked leaves nothing behind.",
        ["script.nuget.return.packages.label"] = "Packages downloaded",
        ["script.nuget.return.packages.hint"] = "The packages this run of the step brought down, one to an item, with the version that was taken. Empty when everything asked for was already there.",
        ["script.nuget.return.error.label"] = "Error message",
        ["script.nuget.return.error.hint"] = "What went wrong when a package could not be brought down: the package that is not there, the feed that could not be reached, or the mistake NuGet itself reports. Empty when it went well.",
        ["script.nuget.return.success.label"] = "Ran without error",
        ["script.nuget.return.success.hint"] = "True when everything asked for is there and ready, false when it is not. A run that ended badly fails the step as well.",
        ["script.nuget.return.exitCode.label"] = "Exit code",
        ["script.nuget.return.exitCode.hint"] = "The code the script ended with; 0 usually means it went well. Kept apart from the message because a script often means something by the code it chose: a 3 can say \"nothing to do today\" without being a failure, and a macro can branch on it once the failure rule has let it carry on.",
        ["browser.exists.name"] = "Web Element Exists",
        ["browser.exists.desc"] = "Looks once for a page element and reports whether it is in the chosen state.",
        ["browser.exists.pageSelector.label"] = "Selector",
        ["browser.exists.pageSelector.hint"] = "One selector to a line, tried in that order; the first line that finds the element is used, so a second survives a redesign. Reads like CSS, or as text=Sign in.",
        ["browser.exists.narrow.label"] = "Condition",
